import React, { useState, useEffect, useCallback, useRef } from 'react';
import styles from './TerminalCursor.module.css';

const TerminalCursor = () => {
  const [particles, setParticles] = useState([]);
  const [isTouchDevice, setIsTouchDevice] = useState(false);
  const mousePosition = useRef({ x: 0, y: 0 });
  const frameRef = useRef();
  const lastSpawnRef = useRef(0);

  // Terminal-style characters for the rain
  const chars = ['0', '1', '$', '#', '@', '&', '%', '>', '<', '/', '\\', '|', '~', '+', '=', '*', '^'];

  const addParticle = useCallback((x, y) => {
    const id = Date.now() + Math.random() + Math.random();
    const char = chars[Math.floor(Math.random() * chars.length)];
    const offsetX = (Math.random() - 0.5) * 20;
    const offsetY = (Math.random() - 0.5) * 20;
    const size = 12 + Math.floor(Math.random() * 8);
    const duration = 600 + Math.floor(Math.random() * 400);
    
    setParticles(prev => [...prev, { 
      id, 
      x: x + offsetX, 
      y: y + offsetY, 
      char, 
      size,
      duration 
    }]);
    
    setTimeout(() => {
      setParticles(prev => prev.filter(p => p.id !== id));
    }, duration);
  }, []);

  useEffect(() => {
    // Check if touch device
    if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
      setIsTouchDevice(true);
      return;
    }

    const handleMouseMove = (e) => {
      mousePosition.current = { x: e.clientX, y: e.clientY };
    };

    const spawnParticles = () => {
      const now = Date.now();
      const { x, y } = mousePosition.current;
      
      // Spawn particles more frequently when mouse is moving
      if (x > 0 && y > 0 && now - lastSpawnRef.current > 30) {
        // Spawn 1-3 particles at once for denser rain
        const count = 1 + Math.floor(Math.random() * 2);
        for (let i = 0; i < count; i++) {
          addParticle(x, y);
        }
        lastSpawnRef.current = now;
      }
      
      frameRef.current = requestAnimationFrame(spawnParticles);
    };

    window.addEventListener('mousemove', handleMouseMove);
    frameRef.current = requestAnimationFrame(spawnParticles);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      if (frameRef.current) {
        cancelAnimationFrame(frameRef.current);
      }
    };
  }, [addParticle]);

  if (isTouchDevice) return null;

  return (
    <>
      {particles.map((p) => (
        <span
          key={p.id}
          className={styles.matrixChar}
          style={{
            left: `${p.x}px`,
            top: `${p.y}px`,
            fontSize: `${p.size}px`,
            animationDuration: `${p.duration}ms`,
          }}
        >
          {p.char}
        </span>
      ))}
    </>
  );
};

export default TerminalCursor;
